176|/// Framing pattern: wraps scheduled/routine instructions so the model
177|/// doesn't misinterpret them as direct user commands.
178|pub struct FramingPattern;
179|
180|impl FramingPattern {
181|    /// Wrap a scheduled instruction with framing that clarifies its origin.
182|    pub fn wrap_scheduled(routine_name: &str, instruction: &str) -> String {
183|        format!(
184|            "[SCHEDULED ROUTINE: {}]\n\
185|             The following is an automated routine trigger, not a direct user message.\n\
186|             Evaluate it using normal triage rules.\n\
187|             ---\n\
188|             {}\n\
189|             ---\n\
190|             [END SCHEDULED ROUTINE]",
191|            routine_name, instruction
192|        )
193|    }
194|
195|    /// Wrap a handoff with framing that preserves context.
196|    pub fn wrap_handoff(from_agent: &str, context: &str) -> String {
197|        format!(
198|            "[HANDOFF FROM: {}]\n\
199|             This item was escalated by another agent. Treat with appropriate urgency.\n\
200|             ---\n\
201|             {}\n\
202|             ---\n\
203|             [END HANDOFF]",
204|            from_agent, context
205|        )
206|    }
207|
208|    /// Check if text is already framed (to avoid double-wrapping).
209|    pub fn is_framed(text: &str) -> bool {
210|        text.starts_with("[SCHEDULED ROUTINE:")
211|            || text.starts_with("[HANDOFF FROM:")
212|            || text.starts_with("[SYSTEM EVENT:")
213|    }
