216|/// Stage 2 model interface — abstracts over the actual LLM call.
217|pub trait TriageModel: Send + Sync {
218|    /// Classify an input that didn't match any Stage 1 rule.
219|    /// Returns a verdict + confidence + reasoning.
220|    /// MUST return Err on failure — never silently default.
221|    fn classify(&self, input: &TriageInput) -> Result<(TriageVerdict, f64, String), TriageError>;
222|
223|    /// Model name for `decided_by` audit field.
224|    fn name(&self) -> &str;
225|}
