227|/// The two-stage triage engine.
228|pub struct TriageEngine {
229|    rules: Vec<TriageRule>,
230|    model: Option<Box<dyn TriageModel>>,
231|    decisions: std::sync::Mutex<Vec<TriageDecision>>,
232|}
233|
234|impl TriageEngine {
235|    pub fn new() -> Self {
236|        Self {
237|            rules: Vec::new(),
238|            model: None,
239|            decisions: std::sync::Mutex::new(Vec::new()),
240|        }
241|    }
242|
243|    /// Add a Stage 1 rule. Validates that rules never produce NeedsYou.
244|    pub fn add_rule(&mut self, rule: TriageRule) -> Result<(), TriageError> {
245|        if matches!(rule.verdict, TriageVerdict::NeedsYou) {
246|            return Err(TriageError::RuleConfig(format!(
247|                "rule '{}' must not produce NeedsYou verdict (reserved for model stage)",
248|                rule.id
249|            )));
250|        }
251|        self.rules.push(rule);
252|        // Keep sorted by priority (ascending = higher priority first)
253|        self.rules.sort_by_key(|r| r.priority);
254|        Ok(())
255|    }
256|
257|    /// Set the Stage 2 model.
258|    pub fn set_model(&mut self, model: Box<dyn TriageModel>) {
259|        self.model = Some(model);
260|    }
261|
262|    /// Run triage on an input. Stage 1 rules first, then Stage 2 model fallback.
263|    pub fn triage(&self, input: &TriageInput) -> Result<TriageDecision, TriageError> {
264|        // Stage 1: try rules in priority order
265|        for rule in &self.rules {
266|            if (rule.matcher)(input) {
267|                let decision = TriageDecision {
268|                    timestamp: Utc::now(),
269|                    item_id: input.id.clone(),
270|                    verdict: rule.verdict.clone(),
271|                    decided_by: format!("rule:{}", rule.id),
272|                    initiator: input.initiator.clone(),
273|                    confidence: 1.0,
274|                    reasoning: format!("Matched rule: {}", rule.description),
275|                };
276|                self.record_decision(&decision);
277|                return Ok(decision);
278|            }
279|        }
280|
281|        // Stage 2: model fallback
282|        let model = self.model.as_ref().ok_or_else(|| {
283|            TriageError::ModelFailure(
284|                "no model configured and no rule matched — cannot produce verdict".into(),
285|            )
286|        })?;
287|
288|        let (verdict, confidence, reasoning) = model.classify(input)?;
289|
290|        let decision = TriageDecision {
291|            timestamp: Utc::now(),
292|            item_id: input.id.clone(),
293|            verdict,
294|            decided_by: format!("model:{}", model.name()),
295|            initiator: input.initiator.clone(),
296|            confidence,
297|            reasoning,
298|        };
299|        self.record_decision(&decision);
300|        Ok(decision)
301|    }
302|
303|    fn record_decision(&self, decision: &TriageDecision) {
304|        let mut decisions = self.decisions.lock().unwrap();
305|        decisions.push(decision.clone());
306|    }
307|
308|    /// Get all recorded decisions.
309|    pub fn decisions(&self) -> Vec<TriageDecision> {
310|        self.decisions.lock().unwrap().clone()
311|    }
312|
313|    /// Get decisions for a specific item.
314|    pub fn decisions_for_item(&self, item_id: &str) -> Vec<TriageDecision> {
315|        self.decisions
316|            .lock()
317|            .unwrap()
318|            .iter()
319|            .filter(|d| d.item_id == item_id)
320|            .cloned()
321|            .collect()
322|    }
323|
324|    /// Count decisions by decided_by source.
325|    pub fn decision_counts(&self) -> HashMap<String, usize> {
326|        let mut counts = HashMap::new();
327|        for d in self.decisions.lock().unwrap().iter() {
328|            *counts.entry(d.decided_by.clone()).or_insert(0) += 1;
329|        }
330|        counts
331|    }
332|
333|    /// Build the Stage 2 prompt for external use (e.g., sending to an LLM API).
334|    pub fn build_model_prompt(input: &TriageInput) -> TriageModelPrompt {
335|        TriageModelPrompt {
336|            system: "You are a triage classifier. Given an inbound item, classify it into exactly one verdict:\n\
337|                     - can_wait: safe to defer, no immediate attention needed\n\
338|                     - needs_you: requires human decision or attention\n\
339|                     - auto_handle:<action>: can be handled automatically (specify action)\n\
340|                     - escalate:<target>: should be escalated to a specific person/team\n\n\
341|                     Respond in JSON: {\"verdict\": \"...\", \"confidence\": 0.0-1.0, \"reasoning\": \"...\"}\n\
342|                     Never guess. If uncertain, prefer needs_you."
343|                .into(),
344|            user: format!(
345|                "Subject: {}\nFrom: {}\nLabels: {:?}\nInitiator: {} ({})\n\nBody:\n{}",
346|                input.subject,
347|                input.sender,
348|                input.labels,
349|                input.initiator.label(),
350|                input.initiator.detail(),
351|                input.body
352|            ),
353|            expected_schema: "{\"verdict\": string, \"confidence\": number, \"reasoning\": string}".into(),
354|        }
355|    }
356|}
