449|/// Eval harness for measuring triage accuracy against a labeled corpus.
450|pub struct TriageEval {
451|    corpus: Vec<EvalCase>,
452|}
453|
454|#[derive(Debug, Clone)]
455|pub struct EvalCase {
456|    pub input: TriageInput,
457|    pub expected_verdict: TriageVerdict,
458|    pub expected_decided_by_prefix: String, // "rule:" or "model:"
459|}
460|
461|#[derive(Debug, Clone, Serialize, Deserialize)]
462|pub struct EvalResult {
463|    pub total: usize,
464|    pub correct: usize,
465|    pub accuracy: f64,
466|    pub by_source: HashMap<String, EvalSourceStats>,
467|    pub failures: Vec<EvalFailure>,
468|}
469|
470|#[derive(Debug, Clone, Serialize, Deserialize)]
471|pub struct EvalSourceStats {
472|    pub total: usize,
473|    pub correct: usize,
474|    pub accuracy: f64,
475|}
476|
477|#[derive(Debug, Clone, Serialize, Deserialize)]
478|pub struct EvalFailure {
479|    pub item_id: String,
480|    pub expected: String,
481|    pub got: String,
482|    pub decided_by: String,
483|}
484|
485|impl TriageEval {
486|    pub fn new(corpus: Vec<EvalCase>) -> Self {
487|        Self { corpus }
488|    }
489|
490|    pub fn run(&self, engine: &TriageEngine) -> Result<EvalResult, TriageError> {
491|        let mut correct = 0;
492|        let mut by_source: HashMap<String, EvalSourceStats> = HashMap::new();
493|        let mut failures = Vec::new();
494|
495|        for case in &self.corpus {
496|            let decision = engine.triage(&case.input)?;
497|            let verdict_match = decision.verdict == case.expected_verdict;
498|            let source_match = decision
499|                .decided_by
500|                .starts_with(&case.expected_decided_by_prefix);
501|
502|            let is_correct = verdict_match && source_match;
503|            if is_correct {
504|                correct += 1;
505|            } else {
506|                failures.push(EvalFailure {
507|                    item_id: case.input.id.clone(),
508|                    expected: format!(
509|                        "{} (via {})",
510|                        case.expected_verdict.to_db(),
511|                        case.expected_decided_by_prefix
512|                    ),
513|                    got: format!("{} (via {})", decision.verdict.to_db(), decision.decided_by),
514|                    decided_by: decision.decided_by.clone(),
515|                });
516|            }
517|
518|            // Track per-source stats
519|            let source_key = if decision.decided_by.starts_with("rule:") {
520|                "rule".to_string()
521|            } else {
522|                "model".to_string()
523|            };
524|            let stats = by_source
525|                .entry(source_key)
526|                .or_insert(EvalSourceStats {
527|                    total: 0,
528|                    correct: 0,
529|                    accuracy: 0.0,
530|                });
531|            stats.total += 1;
532|            if is_correct {
533|                stats.correct += 1;
534|            }
535|        }
536|
537|        // Compute accuracies
538|        for stats in by_source.values_mut() {
539|            stats.accuracy = if stats.total > 0 {
540|                stats.correct as f64 / stats.total as f64
541|            } else {
542|                0.0
543|            };
544|        }
545|
546|        let total = self.corpus.len();
547|        Ok(EvalResult {
548|            total,
549|            correct,
550|            accuracy: if total > 0 {
551|                correct as f64 / total as f64
552|            } else {
553|                0.0
554|            },
555|            by_source,
556|            failures,
557|        })
558|    }
559|}
