128|/// This prevents false-positive urgent alerts from pattern matching.
129|pub fn evaluate_rules(input: &TriageInput, rules: &[TriageRule]) -> Option<TriageVerdict> {
130|    let body_lower = input.body.to_lowercase();
131|    for rule in rules {
132|        if body_lower.contains(&rule.pattern.to_lowercase()) {
133|            // Enforce: rules cannot say needs_you
