138|            return Some(TriageVerdict {
139|                urgency,
140|                decided_by: DecidedBy::Rule(rule.id.clone()),
141|                summary: format!("Matched rule '{}': {}", rule.id, rule.description),
142|                initiator: input.initiator.clone(),
143|            });
144|        }
145|    }
146|    None
