187|/// Parse a model response into a TriageVerdict.
188|/// Model failures throw — they do NOT silently default to any verdict.
189|pub fn parse_model_response(
190|    response: &str,
191|    model_name: &str,
192|    input: &TriageInput,
193|) -> Result<TriageVerdict, TriageError> {
194|    // Extract JSON from response (model may include markdown fences or preamble)
195|    let json_str = extract_json(response).ok_or_else(|| {
196|        TriageError::ParseFailure(format!(
197|            "No JSON object found in model response: {}",
198|            &response[..response.len().min(200)]
199|        ))
200|    })?;
201|
202|    let parsed: serde_json::Value = serde_json::from_str(json_str)
203|        .map_err(|e| TriageError::ParseFailure(format!("Invalid JSON: {e}")))?;
204|
205|    let urgency_str = parsed["urgency"]
206|        .as_str()
207|        .ok_or_else(|| TriageError::ParseFailure("Missing 'urgency' field".into()))?;
208|
209|    let urgency = match urgency_str {
210|        "needs_you" => Urgency::NeedsYou,
211|        "can_wait" => Urgency::CanWait,
212|        "skip" => Urgency::Skip,
213|        other => {
214|            return Err(TriageError::ParseFailure(format!(
215|                "Invalid urgency value: '{other}'"
216|            )))
217|        }
218|    };
219|
220|    let summary = parsed["summary"]
221|        .as_str()
222|        .unwrap_or("(no summary provided)")
223|        .to_string();
224|
225|    Ok(TriageVerdict {
226|        urgency,
227|        decided_by: DecidedBy::Model(model_name.to_string()),
228|        summary,
229|        initiator: input.initiator.clone(),
230|    })
231|}
