233|/// Extract the first JSON object from a string that may contain markdown fences or preamble.
234|fn extract_json(text: &str) -> Option<&str> {
235|    // Try to find ```json ... ``` block first
236|    if let Some(start) = text.find("```json") {
237|        let after_fence = &text[start + 7..];
238|        if let Some(end) = after_fence.find("```") {
239|            return Some(after_fence[..end].trim());
240|        }
241|    }
242|    // Fall back to first { ... } pair
243|    let start = text.find('{')?;
244|    let mut depth = 0;
245|    for (i, ch) in text[start..].char_indices() {
246|        match ch {
247|            '{' => depth += 1,
248|            '}' => {
249|                depth -= 1;
250|                if depth == 0 {
251|                    return Some(&text[start..start + i + 1]);
252|                }
253|            }
254|            _ => {}
255|        }
256|    }
257|    None
