260|/// Full two-stage triage: try rules first, fall back to model.
261|///
262|/// The `model_fn` callback is only called when no rule matches.
263|/// It receives the prompt string and must return the raw model response.
264|pub fn triage<F>(
265|    input: &TriageInput,
266|    rules: &[TriageRule],
267|    model_name: &str,
268|    model_fn: F,
269|) -> Result<TriageVerdict, TriageError>
270|where
271|    F: FnOnce(&str) -> Result<String, String>,
272|{
273|    // Stage 1: rules-only fast path
274|    if let Some(verdict) = evaluate_rules(input, rules) {
275|        return Ok(verdict);
276|    }
277|
278|    // Stage 2: model fallback
279|    let prompt = build_model_prompt(input);
280|    let response = model_fn(&prompt).map_err(TriageError::ModelFailure)?;
281|    parse_model_response(&response, model_name, input)
