21|// ---------------------------------------------------------------------------
22|// Stable hashing helpers
23|// ---------------------------------------------------------------------------
24|
25|/// Strip volatile fields from a JSON value before hashing.
26|/// Removes: snapshot_id, ref, tool_call_id, timestamp, nonce, request_id.
27|pub fn stable(value: &serde_json::Value) -> serde_json::Value {
28|    match value {
29|        serde_json::Value::Object(map) => {
30|            let mut cleaned = serde_json::Map::new();
31|            for (k, v) in map {
32|                let lower = k.to_lowercase();
33|                if lower == "snapshot_id"
34|                    || lower == "ref"
35|                    || lower == "tool_call_id"
36|                    || lower == "timestamp"
37|                    || lower == "nonce"
38|                    || lower == "request_id"
39|                    || lower == "trace_id"
40|                {
41|                    continue;
42|                }
43|                cleaned.insert(k.clone(), stable(v));
44|            }
45|            serde_json::Value::Object(cleaned)
46|        }
47|        serde_json::Value::Array(arr) => {
48|            serde_json::Value::Array(arr.iter().map(stable).collect())
49|        }
50|        other => other.clone(),
51|    }
52|}
53|
54|/// Compute the equivalence hash for an approval request.
55|/// Hash input: `[actor_id, bot_id, tool_ref, effect, scope, stable(target), stable(args)]`
56|pub fn compute_equivalence_hash(
57|    actor_id: &str,
58|    bot_id: &str,
59|    tool_ref: &str,
60|    effect: &str,
61|    scope: &str,
62|    target: &serde_json::Value,
63|    args: &serde_json::Value,
64|) -> String {
65|    let stable_target = stable(target);
66|    let stable_args = stable(args);
67|
68|    let canonical = serde_json::json!([
69|        actor_id,
70|        bot_id,
71|        tool_ref,
72|        effect,
73|        scope,
74|        stable_target,
75|        stable_args
76|    ]);
77|
78|    let bytes = serde_json::to_vec(&canonical).unwrap_or_default();
79|    let hash = Sha256::digest(&bytes);
80|    hex::encode(hash)
81|}
