381|    pub fn submit_approval(
382|        &self,
383|        actor_id: &str,
384|        bot_id: &str,
385|        tool_ref: &str,
386|        effect: &str,
387|        scope: &str,
388|        target: &serde_json::Value,
389|        args: &serde_json::Value,
390|        ttl_seconds: u64,
391|    ) -> SubmitResult {
392|        let hash = compute_equivalence_hash(actor_id, bot_id, tool_ref, effect, scope, target, args);
393|
394|        let mut records = self.records.lock().unwrap();
395|
396|        // Check for existing equivalent approval
397|        if let Some(existing) = records.get(&hash) {
398|            if !existing.is_expired() {
399|                match &existing.state {
400|                    ApprovalState::Approved => {
401|                        return SubmitResult::ReusedApproved(hash);
402|                    }
403|                    ApprovalState::Pending => {
404|                        return SubmitResult::ReusedPending(hash);
405|                    }
406|                    ApprovalState::Declined(reason) => {
407|                        // Re-submitting after decline creates a new record
408|                        // but we inform the caller about the prior decline
409|                        let _ = reason; // acknowledged
410|                    }
411|                    ApprovalState::Expired => {
412|                        // Expired — allow re-submission
413|                    }
414|                }
415|            }
416|        }
417|
418|        let record = ApprovalRecord {
419|            equivalence_hash: hash.clone(),
420|            actor_id: actor_id.into(),
421|            bot_id: bot_id.into(),
422|            tool_ref: tool_ref.into(),
423|            effect: effect.into(),
