435|    }
436|
437|    /// Apply a tier decision to an approval. Higher tiers override lower ones.
438|    /// Safety tier always wins and cannot be overridden.
439|    pub fn apply_tier_decision(
440|        &self,
441|        hash: &str,
442|        decision: TierDecision,
443|    ) -> Result<ApplyResult, String> {
444|        let mut records = self.records.lock().unwrap();
445|        let record = records
446|            .get_mut(hash)
447|            .ok_or_else(|| format!("approval '{}' not found", hash))?;
448|
449|        // Safety tier always wins — checked BEFORE resolved guard so safety
450|        // can override even a previously resolved approval.
451|        if decision.tier == DecisionTier::Safety && !decision.approved {
452|            record.state = ApprovalState::Declined(RefusalReason::SafetyBlock(
453|                decision.rule_id.clone().unwrap_or_else(|| "unknown".into()),
454|            ));
455|            record.resolved_at = Some(Utc::now());
456|            record.final_tier = DecisionTier::Safety;
457|            record.tier_decisions.push(decision);
458|            return Ok(ApplyResult::SafetyBlocked);
459|        }
460|
461|        // Non-safety decisions cannot modify already-resolved approvals.
462|        if record.is_resolved() {
463|            // If resolved by safety, give a specific error mentioning safety.
464|            if record.final_tier == DecisionTier::Safety {
465|                return Err("cannot override a safety-tier decision; safety rules are absolute".into());
466|            }
467|            return Err(format!("approval '{}' is already resolved", hash));
468|        }
469|
470|        // If already decided by safety, nothing can override
471|        if record.final_tier == DecisionTier::Safety {
472|            return Err("cannot override a safety-tier decision; safety rules are absolute".into());
473|        }
474|
475|        // Higher tier overrides lower
476|        if decision.tier >= record.final_tier {
477|            record.final_tier = decision.tier.clone();
478|
479|            if !decision.approved {
480|                let reason = match decision.tier {
481|                    DecisionTier::TeamRule => RefusalReason::TeamPolicyBlock(
482|                        decision.rule_id.clone().unwrap_or_else(|| "team-policy".into()),
483|                    ),
484|                    _ => RefusalReason::DeclinedByPerson(
485|                        decision.rule_id.clone().unwrap_or_else(|| "reviewer".into()),
486|                    ),
487|                };
488|                record.state = ApprovalState::Declined(reason);
489|                // Only resolve (close to further decisions) at TeamRule or above.
490|                // Lower-tier denials remain open so higher tiers can override.
491|                if decision.tier >= DecisionTier::TeamRule {
492|                    record.resolved_at = Some(Utc::now());
493|                }
494|            } else if decision.tier >= DecisionTier::PersonalRule {
495|                // Auto-approve at personal rule level or above
496|                record.state = ApprovalState::Approved;
497|                record.resolved_at = Some(Utc::now());
498|            }
499|        }
500|
501|        record.tier_decisions.push(decision);
502|        Ok(ApplyResult::Applied)
503|    }
504|
505|    /// Get the current state of an approval by hash.
506|    pub fn get_approval(&self, hash: &str) -> Option<ApprovalRecord> {
507|        self.records.lock().unwrap().get(hash).cloned()
508|    }
509|
510|    /// Get the refusal message for a declined approval.
511|    pub fn get_refusal_message(&self, hash: &str) -> Option<String> {
512|        self.records.lock().unwrap().get(hash).and_then(|r| match &r.state {
513|            ApprovalState::Declined(reason) => Some(reason.message()),
514|            _ => None,
515|        })
516|    }
517|
518|    /// Access the escalation tool (always available).
519|    pub fn escalation_tool(&self) -> &EscalationTool {
520|        &self.escalation
521|    }
522|
523|    /// Count approvals by state.
524|    pub fn counts_by_state(&self) -> HashMap<String, usize> {
525|        let mut counts = HashMap::new();
526|        for record in self.records.lock().unwrap().values() {
527|            let key = match &record.state {
528|                ApprovalState::Pending => "pending",
529|                ApprovalState::Approved => "approved",
530|                ApprovalState::Declined(_) => "declined",
531|                ApprovalState::Expired => "expired",
532|            };
533|            *counts.entry(key.to_string()).or_insert(0) += 1;
534|        }
535|        counts
536|    }
