19|pub struct HealthIssue {
20|    /// Normalized signature hash (tool + error category).
21|    pub signature: String,
22|    /// Detector that produced this issue.
23|    pub detector: String,
24|    /// Severity level.
25|    pub severity: Severity,
26|    /// Human-readable summary (PII-free).
27|    pub summary: String,
28|    /// When first observed.
29|    pub first_seen: DateTime<Utc>,
30|    /// When last observed.
31|    pub last_seen: DateTime<Utc>,
32|    /// Occurrence count since first_seen.
33|    pub count: u64,
34|}
