263|// ---------------------------------------------------------------------------
264|// Normalized signature
265|// ---------------------------------------------------------------------------
266|
267|/// Compute a normalized signature from tool name and error message.
268|/// Strips PII, lowercases, trims whitespace, and hashes with SHA-256.
269|pub fn normalize_signature(tool: &str, error: Option<&str>) -> String {
270|    let clean_tool = tool.trim().to_lowercase();
271|    let clean_error = error
272|        .map(|e| strip_pii(e).trim().to_lowercase())
273|        .unwrap_or_default();
274|
275|    let input = format!("{}|{}", clean_tool, clean_error);
276|    let hash = Sha256::digest(input.as_bytes());
277|    hex::encode(&hash[..16]) // 128-bit truncated hash
278|}
