280|// ---------------------------------------------------------------------------
281|// Detectors (pure functions)
282|// ---------------------------------------------------------------------------
283|
284|/// Detect HTTP 5xx errors from observations.
285|pub fn detect_http_5xx(observations: &[Observation]) -> Vec<DetectorFinding> {
286|    observations
287|        .iter()
288|        .filter(|o| o.status_code.map_or(false, |c| c >= 500))
289|        .map(|o| DetectorFinding {
290|            detector: "http_5xx".into(),
291|            severity: Severity::Error,
292|            summary: format!(
293|                "HTTP {} on {}",
294|                o.status_code.unwrap_or(0),
295|                strip_pii(&o.tool)
296|            ),
297|            signature_input: format!(
298|                "{}|{}",
299|                o.tool,
300|                o.error_message.as_deref().unwrap_or("http_5xx")
301|            ),
302|        })
303|        .collect()
304|}
305|
306|/// Detect timeout errors by keyword matching.
307|pub fn detect_timeouts(observations: &[Observation]) -> Vec<DetectorFinding> {
308|    let timeout_keywords = ["timeout", "timed out", "deadline exceeded", "request timed out"];
309|
310|    observations
311|        .iter()
312|        .filter(|o| {
313|            o.error_message
314|                .as_ref()
315|                .map(|msg| {
316|                    let lower = msg.to_lowercase();
317|                    timeout_keywords.iter().any(|kw| lower.contains(kw))
318|                })
319|                .unwrap_or(false)
320|        })
321|        .map(|o| DetectorFinding {
322|            detector: "timeout".into(),
323|            severity: Severity::Warning,
324|            summary: format!("Timeout on {}", strip_pii(&o.tool)),
325|            signature_input: format!("{}|timeout", o.tool),
326|        })
327|        .collect()
328|}
329|
330|/// Detect repeated failures (>= threshold within window).
331|pub fn detect_repeated_failures(
332|    observations: &[Observation],
333|    threshold: usize,
334|) -> Vec<DetectorFinding> {
335|    let mut error_counts: HashMap<String, usize> = HashMap::new();
336|
337|    for o in observations {
338|        if o.error_message.is_some() || o.status_code.map_or(false, |c| c >= 400) {
339|            let key = normalize_signature(&o.tool, o.error_message.as_deref());
340|            *error_counts.entry(key).or_insert(0) += 1;
341|        }
342|    }
343|
344|    error_counts
345|        .into_iter()
346|        .filter(|(_, count)| *count >= threshold)
347|        .map(|(sig, count)| DetectorFinding {
348|            detector: "repeated_failure".into(),
349|            severity: if count >= threshold * 3 {
350|                Severity::Critical
351|            } else {
352|                Severity::Warning
353|            },
354|            summary: format!("Repeated failure pattern: {} occurrences", count),
355|            signature_input: sig,
356|        })
357|        .collect()
358|}
