360|// ---------------------------------------------------------------------------
361|// Issue store (JSONL append-only, upsert by signature)
362|// ---------------------------------------------------------------------------
363|
364|/// In-memory issue store with upsert-by-signature semantics.
365|/// Output is designed to be written as JSONL append-only outside the
366|/// main data directory.
367|pub struct IssueStore {
368|    issues: Mutex<HashMap<String, HealthIssue>>,
369|}
370|
371|impl IssueStore {
372|    pub fn new() -> Self {
373|        Self {
374|            issues: Mutex::new(HashMap::new()),
375|        }
376|    }
377|
378|    /// Upsert an issue by signature. Returns the updated issue.
379|    pub fn upsert(&self, finding: DetectorFinding, now: DateTime<Utc>) -> HealthIssue {
380|        let signature = normalize_signature_from_input(&finding.signature_input);
381|        let mut issues = self.issues.lock().unwrap();
382|
383|        let issue = issues.entry(signature.clone()).or_insert_with(|| HealthIssue {
384|            signature: signature.clone(),
385|            detector: finding.detector.clone(),
386|            severity: finding.severity,
387|            summary: strip_pii(&finding.summary),
388|            first_seen: now,
389|            last_seen: now,
390|            count: 0,
391|        });
392|
393|        issue.last_seen = now;
394|        issue.count += 1;
395|        // Escalate severity if higher
396|        if finding.severity > issue.severity {
397|            issue.severity = finding.severity;
398|        }
399|        // Update summary with latest (always PII-stripped)
400|        issue.summary = strip_pii(&finding.summary);
401|
402|        issue.clone()
403|    }
404|
405|    /// Get all current issues.
406|    pub fn list(&self) -> Vec<HealthIssue> {
407|        self.issues.lock().unwrap().values().cloned().collect()
408|    }
409|
410|    /// Get issue count by severity.
411|    pub fn counts_by_severity(&self) -> HashMap<Severity, u64> {
412|        let mut counts = HashMap::new();
413|        for issue in self.issues.lock().unwrap().values() {
414|            *counts.entry(issue.severity).or_insert(0) += issue.count;
415|        }
416|        counts
417|    }
418|
419|    /// Serialize all issues as JSONL (one JSON object per line).
420|    pub fn to_jsonl(&self) -> String {
421|        let issues = self.issues.lock().unwrap();
422|        let mut lines = Vec::with_capacity(issues.len());
423|        for issue in issues.values() {
424|            if let Ok(json) = serde_json::to_string(issue) {
425|                lines.push(json);
426|            }
427|        }
428|        lines.join("\n")
429|    }
430|}
431|
432|fn normalize_signature_from_input(input: &str) -> String {
433|    let hash = Sha256::digest(input.as_bytes());
434|    hex::encode(&hash[..16])
435|}
