437|// ---------------------------------------------------------------------------
438|// Rate limiter for incident reporting
439|// ---------------------------------------------------------------------------
440|
441|/// Token-bucket rate limiter for team incident reports.
442|/// Default: max_reports per window_seconds.
443|pub struct IncidentRateLimiter {
444|    max_reports: u32,
445|    window_seconds: i64,
446|    reports: Mutex<Vec<DateTime<Utc>>>,
447|}
448|
449|impl IncidentRateLimiter {
450|    pub fn new(max_reports: u32, window_seconds: i64) -> Self {
451|        Self {
452|            max_reports,
453|            window_seconds,
454|            reports: Mutex::new(Vec::new()),
455|        }
456|    }
457|
458|    /// Default: 5 reports per hour.
459|    pub fn default_hourly() -> Self {
460|        Self::new(5, 3600)
461|    }
462|
463|    /// Try to record a report. Returns true if allowed, false if rate-limited.
464|    pub fn try_report(&self, now: DateTime<Utc>) -> bool {
465|        let mut reports = self.reports.lock().unwrap();
466|        let cutoff = now - chrono::Duration::seconds(self.window_seconds);
467|        reports.retain(|t| *t > cutoff);
468|
469|        if reports.len() < self.max_reports as usize {
470|            reports.push(now);
471|            true
472|        } else {
473|            false
474|        }
475|    }
476|
477|    /// Seconds until next report slot opens.
478|    pub fn retry_after_seconds(&self, now: DateTime<Utc>) -> Option<i64> {
479|        let reports = self.reports.lock().unwrap();
480|        let cutoff = now - chrono::Duration::seconds(self.window_seconds);
481|        let active: Vec<_> = reports.iter().filter(|t| **t > cutoff).collect();
482|
483|        if active.len() < self.max_reports as usize {
484|            None
485|        } else {
486|            // Oldest active report expires first
487|            active.iter().min().map(|oldest| {
488|                (**oldest + chrono::Duration::seconds(self.window_seconds) - now).num_seconds().max(0)
489|            })
490|        }
491|    }
492|}
