494|// ---------------------------------------------------------------------------
495|// Sentinel scanner (orchestrates detectors + store + rate limiter)
496|// ---------------------------------------------------------------------------
497|
498|pub struct SentinelScanner {
499|    store: IssueStore,
500|    rate_limiter: IncidentRateLimiter,
501|}
502|
503|impl SentinelScanner {
504|    pub fn new() -> Self {
505|        Self {
506|            store: IssueStore::new(),
507|            rate_limiter: IncidentRateLimiter::default_hourly(),
508|        }
509|    }
510|
511|    pub fn with_rate_limiter(mut self, limiter: IncidentRateLimiter) -> Self {
512|        self.rate_limiter = limiter;
513|        self
514|    }
515|
516|    /// Run all detectors over observations and upsert findings.
517|    pub fn scan(&self, observations: &[Observation], now: DateTime<Utc>) -> Vec<HealthIssue> {
518|        let mut all_findings = Vec::new();
519|        all_findings.extend(detect_http_5xx(observations));
520|        all_findings.extend(detect_timeouts(observations));
521|        all_findings.extend(detect_repeated_failures(observations, 3));
522|
523|        all_findings
524|            .into_iter()
525|            .map(|f| self.store.upsert(f, now))
526|            .collect()
527|    }
528|
529|    /// Report an incident to the team (rate-limited).
530|    pub fn report_incident(&self, signature: &str, severity: Severity, summary: &str, now: DateTime<Utc>) -> IncidentReport {
531|        let allowed = self.rate_limiter.try_report(now);
532|        IncidentReport {
533|            signature: signature.to_string(),
534|            severity,
535|            summary: strip_pii(summary),
536|            reported_at: now,
537|            suppressed: !allowed,
538|        }
539|    }
540|
541|    /// Get current issues.
542|    pub fn issues(&self) -> Vec<HealthIssue> {
543|        self.store.list()
544|    }
545|
546|    /// Export issues as JSONL.
547|    pub fn export_jsonl(&self) -> String {
548|        self.store.to_jsonl()
549|    }
